"use client";
import { RiSearchLine, RiStore2Line } from "@remixicon/react";
import { useRef, useState } from "react";
import { cx } from "../../utils/cx";
import { IconButton } from "../../base/buttons/icon-button";
import { Input } from "../../base/input/input";
import { AgentAvatar } from "../agent-creator/agent-avatar";
import { AgentEditorPanel } from "../agent-creator/agent-editor-panel";
import {
  DEFAULT_AGENT_CONFIGURATION,
  AgentCreator,
  type AgentConfiguration,
} from "../agent-creator/agent-creator";
import { ComposerPanel, type ComposerModel, type ComposerPanelProps } from "../composer/composer";
import { TemplateShell, type TemplateShellProps } from "./template-shell";
import { AgentPicker, AgentAvatarStack } from "../agent-creator/agent-picker";
import type { AgentOption } from "../agent-creator/agent-types";
import {
  AgentConversationActions,
  AgentCreateMenu,
} from "../conversation/agent-conversation-actions";
import { SettingsModal } from "../settings/settings-modal";
import type { SettingsMarketplaceProps } from "../settings/settings-marketplace";
import { ConversationList } from "../conversation/conversation-list";
import { ConversationTopBar } from "./conversation-top-bar";
import { ConversationMessages } from "./conversation-messages";
import {
  useConversationState,
  settleConversationMessages,
  type ConversationAdapter,
  type ConversationMessage,
} from "./conversation-state";
export interface ChatAgent extends AgentOption {
  summary: string;
  prompt: string;
  reply: string;
  demoReply?: string;
}
export const DEFAULT_CHAT_AGENTS: ChatAgent[] = [
  {
    id: "design",
    shape: "slender",
    name: "landing page designer",
    label: "Design",
    description:
      "Thoughtful layouts, clear hierarchy, and a little personality for your next landing page.",
    color: "#abd8c7",
    emotionColor: "#b9dfd0",
    summary:
      "Give the hero one clear action. Lead with the outcome, pair it with a focused product preview, and move the secondary links below the fold.",
    prompt: "How can we make the landing page feel clearer?",
    reply:
      "Give the hero one clear action. Lead with the outcome, pair it with a focused product preview, and move the secondary links below the fold.\n\nFor the next section, show three concrete benefits with short examples. That creates a natural path from understanding the product to trying it.",
  },
  {
    id: "content",
    name: "content reviewer",
    label: "Writing",
    description: "Makes your writing clear, concise, and unmistakably yours.",
    color: "#e7bc9d",
    emotionColor: "#ebc7ad",
    summary: "The shorter opening feels more welcoming. Start with a quick summary.",
    prompt: "Can you review this introduction?",
    reply:
      "The shorter opening feels more welcoming. Start with the main benefit and give the reader one clear next step.",
  },
  {
    id: "marketing",
    name: "marketing bot",
    label: "Marketing",
    description: "Turns a good idea into a campaign people remember.",
    color: "#a5dfde",
    emotionColor: "#b4e4e3",
    shape: "spark",
    summary:
      "Build the campaign around one before-and-after story, then adapt it for email, social, and the launch page.",
    prompt: "How should we plan the launch?",
    reply:
      "Build the campaign around one before-and-after story, then adapt it for email, social, and the launch page.",
  },
  {
    id: "seo",
    name: "seo bot",
    label: "SEO",
    description: "Helps the right people discover your work through search.",
    color: "#ab9aea",
    emotionColor: "#b9abed",
    shape: "flower",
    summary:
      "Start with a practical guide to the core topic. Support it with focused articles that answer the next questions readers are likely to ask.",
    prompt: "Which guide should we write first?",
    reply:
      "Start with a practical guide to the core topic. Support it with focused articles that answer the next questions readers are likely to ask.",
  },
  {
    id: "research",
    name: "research assistant",
    label: "Research",
    description: "Connects the dots, asks better questions, and brings the evidence.",
    color: "#f3d791",
    emotionColor: "#f5dea3",
    shape: "petal",
    summary:
      "Ask about the last time the problem happened. Have customers walk through what they tried, where they got stuck, and what a good result would have looked like.",
    prompt: "What should we ask customers?",
    reply:
      "Ask about the last time the problem happened. Have customers walk through what they tried, where they got stuck, and what a good result would have looked like.",
  },
  {
    id: "security",
    name: "Security agent",
    label: "Security",
    description:
      "A careful second pair of eyes for permissions, privacy, and application security.",
    color: "#a4dfe0",
    emotionColor: "#b3e4e5",
    shape: "shield",
    summary:
      "Review access permissions before inviting testers. Confirm that every request checks the current user’s access and that one account cannot read another account’s data.",
    prompt: "What should we check before inviting testers?",
    reply:
      "Review access permissions before inviting testers. Confirm that every request checks the current user’s access and that one account cannot read another account’s data.",
  },
  {
    id: "cloud",
    name: "Cloud engineer",
    label: "Cloud",
    description:
      "Helps with server architecture, cloud infrastructure, deployments, and reliable services.",
    color: "#f0af93",
    emotionColor: "#f3bca5",
    shape: "cloud",
    summary:
      "Give staging its own environment and data. Match the production configuration closely, while keeping credentials, storage, and deployment permissions separate.",
    prompt: "How should we configure staging?",
    reply:
      "Give staging its own environment and data. Match the production configuration closely, while keeping credentials, storage, and deployment permissions separate.",
  },
];
const initial = (agent: ChatAgent): ConversationMessage[] => [
  ...(agent.prompt
    ? [{ id: agent.id + "-user", role: "user" as const, content: agent.prompt }]
    : []),
  ...(agent.reply
    ? [{ id: agent.id + "-reply", role: "assistant" as const, content: agent.reply }]
    : []),
];
const EXTRA_CHAT_AGENTS: ChatAgent[] = [
  {
    id: "product",
    name: "Product planner",
    label: "Product",
    description: "Turns a goal into clear milestones and useful next steps.",
    color: "#8eb0f6",
    emotionColor: "#a1bef7",
    shape: "diamond",
    summary: "Turn a goal into clear next steps.",
    prompt: "What should we work on next?",
    reply:
      "Start with the outcome, identify the smallest useful step, and check it with the people who will use it.",
  },
  {
    id: "support",
    name: "Support guide",
    label: "Support",
    description: "Helps people find clear answers and a useful next step.",
    color: "#a3e1bd",
    emotionColor: "#b2e6c8",
    shape: "heart",
    summary: "Find a useful answer and the next step.",
    prompt: "How can we help?",
    reply:
      "Start by confirming the problem, then share one clear action and check whether it resolves the issue.",
  },
  {
    id: "data",
    name: "Data analyst",
    label: "Data",
    description: "Finds patterns and explains what the evidence supports.",
    color: "#8eb0f6",
    emotionColor: "#a1bef7",
    shape: "pocket",
    summary: "Find the pattern behind the numbers.",
    prompt: "What does the data show?",
    reply:
      "Check the data and its limits first, then compare the result with a useful baseline before drawing a conclusion.",
  },
];
const configurationFor = (agent: AgentOption): AgentConfiguration => ({
  ...DEFAULT_AGENT_CONFIGURATION,
  name: agent.name,
  label: agent.label ?? agent.name,
  description: agent.description ?? "",
  color: agent.color,
  emotionColor: agent.emotionColor ?? agent.color,
  shape: agent.shape ?? "robot",
});
export interface MultiAgentChatTemplateProps
  extends Pick<TemplateShellProps, "contained" | "className" | "account" | "team"> {
  agents?: ChatAgent[];
  models?: ComposerModel[];
  composer?: Omit<ComposerPanelProps, "value" | "onValueChange" | "onSubmit" | "onStop" | "busy">;
  onSend?: ConversationAdapter;
  agentConfiguration?: AgentConfiguration;
  defaultEditorOpen?: boolean;
  onAgentChange?: (configuration: AgentConfiguration) => void;
  createAgent?: () => ChatAgent;
  onAgentCreate?: (agent: ChatAgent) => void;
  onAgentUpdate?: (agentId: string, configuration: AgentConfiguration) => void;
  onEditorAgentChange?: (agentId: string) => void;
  marketplace?: Omit<SettingsMarketplaceProps, "onClose">;
}
export function MultiAgentChatTemplate({
  agents = DEFAULT_CHAT_AGENTS,
  models,
  composer,
  onSend,
  agentConfiguration,
  defaultEditorOpen = true,
  onAgentChange,
  createAgent,
  onAgentCreate,
  onAgentUpdate,
  onEditorAgentChange,
  marketplace,
  ...shell
}: MultiAgentChatTemplateProps = {}) {
  const fallback = DEFAULT_CHAT_AGENTS[0];
  const [overrides, setOverrides] = useState<Record<string, Partial<ChatAgent>>>({});
  const [createdAgents, setCreatedAgents] = useState<ChatAgent[]>([]);
  const [createdOrder, setCreatedOrder] = useState<string[]>([]);
  const pool = [
    ...createdAgents,
    ...agents,
    ...EXTRA_CHAT_AGENTS.filter((a) => !agents.some((b) => a.id === b.id)),
  ].map((a) => ({ ...a, ...overrides[a.id] }));
  const pickerOrder = [
    "design",
    "content",
    "marketing",
    "seo",
    "research",
    "security",
    "product",
    "cloud",
    "support",
    "data",
  ];
  const pickerPool = [...pool].sort(
    (a, b) =>
      (pickerOrder.indexOf(a.id) < 0 ? 100 : pickerOrder.indexOf(a.id)) -
      (pickerOrder.indexOf(b.id) < 0 ? 100 : pickerOrder.indexOf(b.id)),
  );
  const [activeId, setActiveId] = useState(agents[0]?.id ?? fallback.id);
  const active = pool.find((a) => a.id === activeId) ?? fallback;
  const [groups, setGroups] = useState<{ id: string; agentIds: string[] }[]>([]),
    [groupId, setGroupId] = useState<string | null>(null);
  const group = groups.find((g) => g.id === groupId);
  const participants = group
    ? group.agentIds.map((id) => pool.find((a) => a.id === id)).filter((a): a is ChatAgent => !!a)
    : [active];
  const title = group ? participants.map((a) => a.label || a.name).join(" + ") : active.name;
  const conversationId = group?.id ?? active.id;
  const initialEditor = agents.find((a) => a.id === "security") ?? agents[0] ?? fallback;
  const [editorId, setEditorId] = useState(initialEditor.id);
  const [configuration, setConfiguration] = useState(() => configurationFor(initialEditor));
  const configurations = useRef(new Map<string, AgentConfiguration>());
  const [query, setQuery] = useState(""),
    [search, setSearch] = useState(false),
    [editorOpen, setEditorOpen] = useState(defaultEditorOpen),
    [picker, setPicker] = useState(false),
    [marketplaceOpen, setMarketplaceOpen] = useState(false);
  const conversation = useConversationState({
    initialMessages: initial(active),
    onSend,
    demoReply: active.demoReply ?? active.reply,
    demoTiming: { thinkingMs: 2800, firstParticipantThinkingMs: 3600, chunkMs: 48 },
    agentId: active.id,
    participants: group
      ? participants.map((a) => ({ agentId: a.id, demoReply: a.demoReply ?? a.reply }))
      : undefined,
  });
  const histories = useRef(new Map<string, ConversationMessage[]>());
  const selectConversation = (id: string) => {
    histories.current.set(conversationId, settleConversationMessages(conversation.messages));
    const nextGroup = groups.find((g) => g.id === id);
    setGroupId(nextGroup?.id ?? null);
    if (!nextGroup) setActiveId(id);
    const agent = pool.find((a) => a.id === id) ?? fallback;
    conversation.reset(histories.current.get(id) ?? (nextGroup ? [] : initial(agent)));
  };
  const openEditor = (agent: AgentOption) => {
    setEditorId(agent.id);
    setConfiguration(configurations.current.get(agent.id) ?? configurationFor(agent));
    onEditorAgentChange?.(agent.id);
    setEditorOpen(true);
  };
  const startGroup = (selected: AgentOption[]) => {
    histories.current.set(conversationId, settleConversationMessages(conversation.messages));
    const id = `group-${crypto.randomUUID()}`;
    setGroups((old) => [{ id, agentIds: selected.map((a) => a.id) }, ...old]);
    setCreatedOrder((old) => [id, ...old]);
    setGroupId(id);
    conversation.reset([]);
  };
  const createNewAgent = () => {
    histories.current.set(conversationId, settleConversationMessages(conversation.messages));
    let number = 2;
    while (pool.some((a) => a.name === `Product planner ${number}`)) number++;
    const preset = pool.find((a) => a.id === "product") ?? EXTRA_CHAT_AGENTS[0];
    const agent = createAgent?.() ?? {
      ...preset,
      id: `agent-${crypto.randomUUID()}`,
      name: `Product planner ${number}`,
      label: "",
      description: "",
      summary: "Start a conversation",
      prompt: "",
      reply: "",
      demoReply: preset.reply,
    };
    if (pool.some((existing) => existing.id === agent.id)) {
      selectConversation(agent.id);
      openEditor(agent);
      return;
    }
    setCreatedAgents((old) => [agent, ...old]);
    setCreatedOrder((old) => [agent.id, ...old]);
    setGroupId(null);
    setActiveId(agent.id);
    conversation.reset([]);
    onAgentCreate?.(agent);
    openEditor(agent);
  };
  const navigation = (onNavigate: () => void) => (
    <ConversationList
      selectedId={conversationId}
      query={query}
      onSelect={(id) => {
        selectConversation(id);
        onNavigate();
      }}
      items={[
        ...createdOrder.map((id) => {
          const group = groups.find((g) => g.id === id);
          if (group) {
            const members = group.agentIds
              .map((id) => pool.find((a) => a.id === id))
              .filter((a): a is ChatAgent => !!a);
            return {
              id: group.id,
              name: members.map((a) => a.label || a.name).join(" + "),
              summary:
                (group.id === groupId
                  ? conversation.messages
                  : histories.current.get(group.id)
                )?.at(-1)?.content ?? "Start a conversation",
              agents: members,
            };
          }
          const agent = pool.find((a) => a.id === id)!;
          return { id: agent.id, name: agent.name, summary: agent.summary, agents: [agent] };
        }),
        ...agents
          .map((a) => pool.find((p) => p.id === a.id) ?? a)
          .map((a) => ({ id: a.id, name: a.name, summary: a.summary, agents: [a] })),
      ]}
    />
  );
  const editorBody = (
    <AgentCreator
      value={agentConfiguration ?? configuration}
      onChange={(next) => {
        setConfiguration(next);
        configurations.current.set(editorId, next);
        if (!agentConfiguration)
          setOverrides((old) => ({
            ...old,
            [editorId]: {
              ...old[editorId],
              name: next.name,
              label: next.label,
              description: next.description,
              color: next.color,
              emotionColor: next.emotionColor,
              shape: next.shape,
            },
          }));
        onAgentChange?.(next);
        onAgentUpdate?.(editorId, next);
      }}
      onClose={() => setEditorOpen(false)}
    />
  );
  return (
    <>
      <SettingsModal
        isOpen={marketplaceOpen}
        onClose={() => setMarketplaceOpen(false)}
        defaultPage="marketplace"
        marketplace={marketplace}
      />
      <TemplateShell
        {...shell}
        variant="workspace"
        navigationBreakpoint="md"
        title={title}
        navigation={({ onNavigate }) => navigation(onNavigate)}
        sidebarOptions={{
          settings: { marketplace: marketplace ?? {} },
          showThemeToggle: false,
          className: "p-[7px]",
          header: ({ onNavigate }) => (
            <div className="flex items-center gap-2">
              {search ? (
                <Input
                  aria-label="Search conversations"
                  placeholder="Search"
                  value={query}
                  onChange={setQuery}
                />
              ) : (
                <>
                  <IconButton
                    icon={RiSearchLine}
                    className="w-auto min-w-0 flex-1 rounded-full border-0 bg-background-tertiary-default shadow-none"
                    aria-label="Search conversations"
                    onClick={() => setSearch(true)}
                  />
                  <IconButton
                    icon={RiStore2Line}
                    className="w-auto min-w-0 flex-1 rounded-full border-0 bg-background-tertiary-default shadow-none"
                    aria-label="Agent store"
                    onClick={() => {
                      onNavigate();
                      setMarketplaceOpen(true);
                    }}
                  />
                  <AgentCreateMenu
                    onCreate={() => {
                      onNavigate();
                      createNewAgent();
                    }}
                    onGroup={() => {
                      onNavigate();
                      setPicker(true);
                    }}
                  />
                </>
              )}
            </div>
          ),
        }}
        workspaceHeader={({ onOpenNavigation, navigationTriggerRef, navigationOpen }) => (
          <ConversationTopBar
            title={title}
            menuClassName="md:hidden"
            avatar={
              group ? (
                <AgentAvatarStack agents={participants} size="compact" />
              ) : (
                <AgentAvatar
                  color={active.color}
                  shape={active.shape}
                  className="size-5 rounded-md"
                />
              )
            }
            onOpenNavigation={onOpenNavigation}
            navigationTriggerRef={navigationTriggerRef}
            navigationOpen={navigationOpen}
            onOptions={() => openEditor(active)}
            actions={
              <AgentConversationActions
                participants={participants}
                transcript={conversation.messages
                  .map((m) => `${m.role}: ${m.content}`)
                  .join("\n\n")}
                onEdit={openEditor}
                onStartGroup={() => setPicker(true)}
              />
            }
          />
        )}
        panel={
          <AgentEditorPanel isOpen={editorOpen} onOpenChange={setEditorOpen}>
            {editorBody}
          </AgentEditorPanel>
        }
        overlays={
          <>
            <AgentPicker
              isOpen={picker}
              onOpenChange={setPicker}
              agents={pickerPool}
              initialSelectedIds={participants.map((a) => a.id)}
              onStart={startGroup}
            />
          </>
        }
      >
        {!conversation.messages.length ? (
          <div
            aria-label="Messages"
            tabIndex={0}
            className="flex min-h-0 flex-1 items-center justify-center overflow-y-auto px-6 text-center outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-border-focus-ring"
          >
            <div className="flex flex-col items-center gap-4">
              <AgentAvatarStack agents={participants} />
              <div className="flex flex-col items-center gap-1.5">
                <h1 className="text-title-3-semibold text-text-primary">
                  {group ? "A few minds. One conversation." : `Say hello to ${active.name}`}
                </h1>
                {group && (
                  <p className="max-w-[420px] text-body-regular text-text-secondary">
                    {participants.map((a) => a.name).join(", ")} are here. Send a message to get
                    everyone’s perspective.
                  </p>
                )}
              </div>
            </div>
          </div>
        ) : (
          <ConversationMessages
            key={conversationId}
            messages={conversation.messages}
            renderAuthor={(message) => {
              const agent = pool.find((a) => a.id === (message.agentId ?? active.id));
              return agent
                ? {
                    label: agent.name,
                    avatar: (
                      <AgentAvatar color={agent.color} shape={agent.shape} className="size-5" />
                    ),
                    onSelect: () => openEditor(agent),
                  }
                : undefined;
            }}
          />
        )}
        {conversation.error && (
          <p role="alert" className="px-4 text-body-regular text-status-rose-text">
            {conversation.error}
          </p>
        )}
        <div className="shrink-0 p-1">
          <ComposerPanel
            {...composer}
            expandedOnMobile
            defaultModel={composer?.defaultModel ?? (!models && !composer?.models ? "fable-5" : undefined)}
            defaultPermission={composer?.defaultPermission ?? "bypass"}
            status={composer?.status ?? null}
            className={cx("max-w-none", composer?.className)}
            surfaceClassName={cx("rounded-[var(--radius-2-5xl)]", composer?.surfaceClassName)}
            models={models ?? composer?.models}
            value={conversation.input}
            onValueChange={conversation.setInput}
            onSubmit={(text) => void conversation.send(text)}
            busy={conversation.busy}
            onStop={conversation.stop}
          />
        </div>
      </TemplateShell>
    </>
  );
}
